48.                 .map(f -> (MicrometerConfigurationHook) ContributionManager.INSTANCE.createInstance(MicrometerConfigurationHookContributor.class, f.type(),
49.                         wrap(f.config())))
50.                 .toList();
51.         configurationHooks.forEach(micrometerConfigurationHook -> micrometerConfigurationHook.configure(globalRegistry));
52.         return configurationHooks;
53.     }
