72.                 }
73.                 return MeterFilterReply.ACCEPT;
74.             }
75.         });
76.     }
77. 
78.     private static Object tagNames(Meter.Id id1) {
79.         return id1.getTags().stream().map(Tag::getKey).collect(Collectors.toSet());
80.     }
