             Metrics.counter(counter_name).increment();
             HttpResponse<String> response = AdminHttpClient.INSTANCE.getFromAdminEndpoint("metrics");
             assertResponseBodyContainsMeterWithTag(response, counter_name, "a", "b");
         }
