268.         List<Double> values = new ArrayList<>();
269. 
270.         if (collectedData != null && !collectedData.isEmpty()) {
271.             for (Map.Entry<String, String> entry : collectedData.entrySet()) {
272.                 Matcher t = pattern.matcher(entry.getValue());
273.                 if (t.find()) {
