295.                         List<Double> vals = this.collectSpecificMetric(pattern);
296. 
297.                         if (!vals.isEmpty()) {
298.                             values.addAll(vals);
299.                             return true;
300.                         }
301. 
302.                         return false;
303.                     });
304.         }
305. 
306.         return values;
307.     }
