321. 
322.         Message message = LOGGER.getMessageFactory().newMessage("Metrics collection for Pod: {}/{}({}) from Pod: {}/{} finished with return code: {}", namespaceName,
323.                 podName, metricsPodIp, namespaceName, scraperPodName, result.returnCode());
324. 
325.         if (!result.isSuccess()) {
326.             LOGGER.warn(message);
327.         }
328.         else {
